  cmd.push("--to", "html");
  cmd.push("--from", "markdown");
  cmd.push("--template", template);
  cmd.push("--output", filename);
  cmd.push("--metadata", "title=placeholder");
  cmd.push("--embed-resources");
  const result = await execProcess({
    cmd,
    stdout: "piped",
    cwd: workingDir,
  }, input.join("\n"));

  if (result.success) {
    return result.stdout;
  } else {
    throw new Error();
  }
};

